INSERT INTO ACTORDIRECTOR (TIMESTAMP, ACTOR_ID, DIRECTOR_ID) VALUES (2, 101, 201);
INSERT INTO ACTORDIRECTOR (TIMESTAMP, ACTOR_ID, DIRECTOR_ID) VALUES (3, 101, 201);

